/**
 * 环特质.js — 特质数值层（原版锚定）：心情基线 / stat 修正 / 组合效果
 * 条目层只写行为与对白素材，数值一律这里查；供环结算（心情）与环引擎（resolveStat）调用
 */
var 环特质 = (function () {
  'use strict';
  var HOST = typeof window !== 'undefined' ? window : globalThis;

  /* ═══ 特质数值表（原版 wiki 锚定）═══
   * 心情: 心情基线偏移；学习: 学习率乘数；stat: 对指定 stat 的修正；崩溃: 崩溃阈值修正 */
  var DEF = {
    // ── 性格与情绪 ──
    '乐观':     { 心情: +12 },
    '悲观':     { 心情: -6 },
    '抑郁':     { 心情: -10, 说明: '想法消退快，坏记忆缠身' },
    '夜猫子':   { 心情: -6, stat: { 全工作: { 白天: -0.1, 夜晚: +0.2 } } },
    '晨型人':   { 心情: +6, stat: { 全工作: { 早晨: +0.15 } } },
    '嗜血':     { 心情: 0, 事件: { 目睹死亡: +4, 击杀: +6 } },
    '精神病态': { 心情: 0, 事件: { 目睹死亡: 0, 他人痛苦: 0 }, 社交: -1, 崩溃: '+抗性' },
    '食人者':   { 事件: { 吃人肉: +6 } },
    '苦行':     { 心情: 0, 期望: '财富高于期望时心情倒扣' },
    '贪吃':     { 心情: +4, 需求: { 饥饿: 1.5 } },
    '工作狂':   { 需求: { 娱乐: 0.5 }, 心情: 0, 事件: { 无活可干: -6 } },
    '懒惰':     { stat: { 全工作: { 常态: -0.15 } } },
    '勤勉':     { stat: { 全工作: { 常态: +0.15 } } },
    '纵火狂':   { 事件: { 看火: +4 }, 风险: '压力下可能自发放火' },
    '神经质':   { stat: { 全工作: { 常态: +0.35 } }, 崩溃: '阈值降低，碎得快' },
    '钢铁意志': { 崩溃: '阈值大幅提高' },
    '懦夫':     { 崩溃: '疼痛阈值极低，易倒地' },
    '温柔':     { 社交: +1, 事件: { 救助他人: +3 }, 特权: '从不侮辱人' },
    '刺头':     { 社交: -1, stat: { 谈判: { 常态: +0.1 } } },
    '羞涩':     { 需求: { 社交: 0.6 } },
    '话痨':     { 需求: { 社交: 1.4 } },
    '独行侠':   { 事件: { 独处: +5, 群处: -5 } },
    '嫉妒':     { 事件: { 他人装备更好: -3 } },
    '贪婪':     { 期望: '财富低于期望时心情重罚' },
    // ── 能力与癖好 ──
    '太聪明':   { stat: { 研究速度: { 常态: +0.35 } }, 风险: '崩溃时疯得花样百出' },
    '好记性':   { 说明: '技能永不衰退' },
    '快速学习': { 学习: 1.75 },
    '迟钝学习': { 学习: 0.6 },
    '裸体主义': { 事件: { 裸体: +6, 穿衣: -4 } },
    '绿拇指':   { stat: { 种植速度: { 常态: +0.2 } }, 事件: { 身处花园: +3 } },
    '稳健射手': { stat: { 射击精度: { 常态: +0.3 } }, 战斗: '射速降低' },
    '乱枪打鸟': { stat: { 射击精度: { 常态: -0.25 } }, 战斗: '射速提升' },
    '斗殴者':   { stat: { 近战: { 常态: +0.3 } }, 战斗: '持枪时心情不爽' },
    '化学兴趣': { 事件: { 用药: +8 } },
    '戒断者':   { 事件: { 用药: -8 } },
    '美丽':     { 社交: +2 },
    '嗓音烦人': { 社交: -2 },
    '温室人':   { 自创: true, 事件: { 首次踏足地表: -10 }, 说明: '轨道站出身，对重力/天气/土地的感官过载' },
  };

  /* ═══ 组合效果 ═══ */
  var 组合 = {
    '嗜血+精神病态': '把战场当舞台，杀戮是表演，战后检查尸体像收藏家',
    '夜猫子+太聪明': '深夜独自研究是唯一稳定的作息，白天基本废',
    '刺头+温柔': '嘴上不饶人但永远第一个冲上去救人——人们骂着骂着就不骂了',
    '嫉妒+贪婪': '行走的抱怨机器，看谁都不顺眼',
    '神经质+工作狂': '高产出与碎裂只隔一条线',
    '绿拇指+食人者': '种得一手好菜，也吃得出人肉哪块最嫩——别问',
  };

  /* ═══ 接口 ═══ */
  function 解析(特质串) {
    return (特质串 || '').split('、').filter(Boolean);
  }
  // 心情基线偏移（环结算每半天用）
  function 心情基线(特质串) {
    var v = 0;
    for (var t of 解析(特质串)) v += (DEF[t] && DEF[t].心情) || 0;
    return v;
  }
  // stat 乘数（环引擎 resolveStat 的特质接入点）
  function stat乘数(特质串, statId, 时段) {
    var m = 1;
    for (var t of 解析(特质串)) {
      var d = DEF[t];
      if (!d || !d.stat) continue;
      var s = d.stat[statId] || d.stat['全工作'];
      if (!s) continue;
      var k = s[时段 || '常态'];
      if (typeof k === 'number') m += k;
    }
    return Math.max(0.1, m);
  }
  // 事件心情修正（想法堆栈生成时查）
  function 事件修正(特质串, 事件) {
    var sum = 0;
    for (var t of 解析(特质串)) {
      var d = DEF[t];
      if (d && d.事件 && d.事件[事件] != null) sum += d.事件[事件];
    }
    return sum;
  }
  function 学习率(特质串) {
    var m = 1;
    for (var t of 解析(特质串)) { var d = DEF[t]; if (d && d.学习) m *= d.学习; }
    return m;
  }
  function 组合效果(特质串) {
    var ts = 解析(特质串), out = [];
    for (var k in 组合) {
      var parts = k.split('+');
      if (ts.indexOf(parts[0]) >= 0 && ts.indexOf(parts[1]) >= 0) out.push(组合[k]);
    }
    return out;
  }

  var API = { 版本: '1.0.0', DEF: DEF, 组合: 组合, 解析: 解析, 心情基线: 心情基线, stat乘数: stat乘数, 事件修正: 事件修正, 学习率: 学习率, 组合效果: 组合效果 };
  try { HOST.Rimworld = HOST.Rimworld || {}; HOST.Rimworld.traits = API; } catch (e) {}
  globalThis.环特质 = API;
  return API;
})();
